BEGIN;
-- Private schema: the browser never queries the Supabase Data API.
CREATE SCHEMA IF NOT EXISTS glowbb;
REVOKE ALL ON SCHEMA glowbb FROM PUBLIC, anon, authenticated;
CREATE TABLE IF NOT EXISTS glowbb.schema_version(version INTEGER PRIMARY KEY);
INSERT INTO glowbb.schema_version VALUES(1) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS glowbb.users(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','planner','viewer')));
CREATE TABLE IF NOT EXISTS glowbb.logins(token TEXT PRIMARY KEY,user_id INTEGER REFERENCES glowbb.users(id),expires DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS glowbb.participants(id TEXT PRIMARY KEY,details TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS glowbb.programmes(id TEXT PRIMARY KEY,name TEXT NOT NULL,domain TEXT NOT NULL,optional TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS glowbb.sessions(id TEXT PRIMARY KEY,programme_id TEXT NOT NULL REFERENCES glowbb.programmes(id),date TEXT NOT NULL,start INTEGER NOT NULL,"end" INTEGER NOT NULL,venue TEXT,optional TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS glowbb.attendance(id TEXT PRIMARY KEY,participant_id TEXT NOT NULL REFERENCES glowbb.participants(id),session_id TEXT NOT NULL REFERENCES glowbb.sessions(id),source_session TEXT NOT NULL,import_id INTEGER);
CREATE TABLE IF NOT EXISTS glowbb.imports(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,created TEXT NOT NULL,user_id INTEGER NOT NULL REFERENCES glowbb.users(id),summary TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS glowbb.settings(id INTEGER PRIMARY KEY CHECK(id=1),value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS glowbb.targets(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,metric TEXT NOT NULL,value INTEGER NOT NULL,start TEXT NOT NULL,"end" TEXT NOT NULL,programme_id TEXT REFERENCES glowbb.programmes(id));
CREATE TABLE IF NOT EXISTS glowbb.decisions(programme_id TEXT PRIMARY KEY REFERENCES glowbb.programmes(id),status TEXT NOT NULL,notes TEXT NOT NULL,updated TEXT NOT NULL,user_id INTEGER NOT NULL REFERENCES glowbb.users(id));
CREATE TABLE IF NOT EXISTS glowbb.opportunity_decisions(target_id INTEGER PRIMARY KEY REFERENCES glowbb.targets(id) ON DELETE CASCADE,status TEXT NOT NULL,notes TEXT NOT NULL,updated TEXT NOT NULL,user_id INTEGER NOT NULL REFERENCES glowbb.users(id));
CREATE TABLE IF NOT EXISTS glowbb.audit(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,created TEXT NOT NULL,user_id INTEGER,action TEXT NOT NULL,details TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS glowbb.import_previews(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES glowbb.users(id),expires DOUBLE PRECISION NOT NULL,payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_date ON glowbb.sessions(date);
CREATE INDEX IF NOT EXISTS attendance_session ON glowbb.attendance(session_id);
INSERT INTO glowbb.settings VALUES(1,'{"seniorAge":60,"minority":["MALAY","INDIAN","OTHERS"],"ageBands":[70,80],"minSessions":3,"minParticipants":5,"privacyMinimum":5}') ON CONFLICT DO NOTHING;
INSERT INTO glowbb.users(username,password,role) VALUES('__local_workspace__','disabled','admin') ON CONFLICT DO NOTHING;
-- No policies are needed: access is through the server's PostgreSQL connection.
DO $$ DECLARE t RECORD; BEGIN
  FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='glowbb' LOOP
    EXECUTE format('ALTER TABLE glowbb.%I ENABLE ROW LEVEL SECURITY', t.tablename);
    EXECUTE format('REVOKE ALL ON TABLE glowbb.%I FROM PUBLIC, anon, authenticated', t.tablename);
  END LOOP;
END $$;
COMMIT;
